enum LevelOfTutoring {
  PrimarySchool
  HighSchool
  University
}

enum PaymentKind {
  CreditCard
  WireTransfer
}

abstract class TutoringRole {
}

class User {
  +name : string
  +emailAddress : string
}

class Student extends TutoringRole {
}

class Tutor extends TutoringRole {
  +bankAccount : string
}

class Subject {
}

class TutoringOffer {
  +levelOfExpertise : LevelOfTutoring
  +hourlyPrice : float
}

class TutorAvailability {
  +dayOfWeek : string
  +startTime : time
  +endTime : time
}

class TutoringRequest {
  +levelOfTutoring : LevelOfTutoring
  +targetDate : date
  +targetTime : time
}

class TutoringSession {
}

class Payment {
  +amount : float
}

class BestTutorAward {
}

User "1" -- "0..2" TutoringRole

Tutor "1" *-- "*" TutoringOffer
Tutor "1" *-- "*" TutorAvailability
Tutor "1" -- "*" BestTutorAward
Subject "1" -- "*" TutoringOffer
Subject "1" -- "*" BestTutorAward

Student "1" -- "*" TutoringRequest
TutoringRequest "*" -- "1" Tutor : designated tutor
TutoringRequest "1" -- "1" TutoringSession : first session
TutoringRequest "1" -- "0..1" TutoringSession : next session

TutoringSession "1" -- "1" Student : participant
TutoringSession "1" -- "1" Tutor : participant
TutoringSession "1" -- "0..1" Payment : paid for

@enduml

